'use strict';

const fs = require('fs');
const tokens = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

let pos = 0;
const N = Number(tokens[pos++]);
const X1 = BigInt(tokens[pos++]);
const X2 = BigInt(tokens[pos++]);

const lines = [];

for (let i = 0; i < N; i++) {
  const a = BigInt(tokens[pos++]);
  const b = BigInt(tokens[pos++]);
  lines.push({
    a,
    y1: a * X1 + b,
    y2: a * X2 + b,
    id: i
  });
}

const byStart = lines.slice().sort((u, v) => {
  if (u.y1 < v.y1) return -1;
  if (u.y1 > v.y1) return 1;
  if (u.a > v.a) return -1;
  if (u.a < v.a) return 1;
  return 0;
});

const byEnd = lines.slice().sort((u, v) => {
  if (u.y2 < v.y2) return -1;
  if (u.y2 > v.y2) return 1;
  if (u.a < v.a) return -1;
  if (u.a > v.a) return 1;
  return 0;
});

const rank = new Int32Array(N);
for (let i = 0; i < N; i++) {
  rank[byEnd[i].id] = i;
}

const bit = new Int32Array(N + 1);
let inversions = 0;

for (let i = 0; i < N; i++) {
  const r = rank[byStart[i].id];
  let countAtMost = 0;

  for (let j = r + 1; j > 0; j -= j & -j) {
    countAtMost += bit[j];
  }

  inversions += i - countAtMost;

  for (let j = r + 1; j <= N; j += j & -j) {
    bit[j]++;
  }
}

console.log(String(inversions));
